/// 引导页面
class OnboardingPage extends StatefulWidget {
  const OnboardingPage({super.key});

  @override
  State<OnboardingPage> createState() => _OnboardingPageState();
}

class _OnboardingPageState extends State<OnboardingPage> {
  final PageController _pageController = PageController();
  int _currentPage = 0;

  @override
  void dispose() {
    _pageController.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final l10n = AppLocalizations.of(context)!;
    return Scaffold(
      body: SafeArea(
        child: Column(
          children: [
            // 跳过按钮
            if (_currentPage == 0)
              Align(
                alignment: Alignment.topRight,
                child: Padding(
                  padding: const EdgeInsets.all(16.0),
                  child: TextButton(
                    onPressed: _completeOnboarding,
                    child: Text(l10n.skip),
                  ),
                ),
              )
            else
              const SizedBox(height: 56),

            // 页面内容
            Expanded(
              child: PageView(
                controller: _pageController,
                onPageChanged: (index) {
                  setState(() {
                    _currentPage = index;
                  });
                },
                children: const [
                  _ScrollableOnboardingPage(child: _WelcomePage()),
                  _ScrollableOnboardingPage(child: _RulesBoardPage()),
                  _ScrollableOnboardingPage(child: _RulesMovementPage()),
                  _ScrollableOnboardingPage(child: _RulesCapturePage()),
                  _ScrollableOnboardingPage(child: _FeaturesPage()),
                ],
              ),
            ),

            // 页面指示器
            _PageIndicator(
              currentPage: _currentPage,
              pageCount: 5,
            ),

            // 导航按钮
            Padding(
              padding: UIConstants.paddingLarge,
              child: Row(
                mainAxisAlignment: MainAxisAlignment.spaceBetween,
                children: [
                  // 上一页按钮
                  if (_currentPage > 0)
                    TextButton.icon(
                      onPressed: () {
                        _pageController.previousPage(
                          duration: UIConstants.pageTransitionDuration,
                          curve: Curves.easeInOut,
                        );
                      },
                      icon: const Icon(Icons.arrow_back),
                      label: Text(l10n.previous),
                    )
                  else
                    const Spacer(),

                  // 下一页/开始按钮
                  FilledButton(
                    onPressed: () {
                      if (_currentPage < 4) {
                        _pageController.nextPage(
                          duration: UIConstants.pageTransitionDuration,
                          curve: Curves.easeInOut,
                        );
                      } else {
                        _completeOnboarding();
                      }
                    },
                    style: ElevatedButton.styleFrom(
                      padding: const EdgeInsets.symmetric(
                        horizontal: 32,
                        vertical: 16,
                      ),
                    ),
                    child: Text(
                      _currentPage < 4 ? l10n.next : l10n.startGame,
                    ),
                  ),
                ],
              ),
            ),
          ],
        ),
      ),
    );
  }

  Future<void> _completeOnboarding() async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setBool(StorageConstants.keyFirstLaunch, false);

    if (mounted) {
      Navigator.of(context).pushReplacementNamed('/home');
    }
  }
}

