/// 棋盘演示绘制器
class _BoardDemoPainter extends CustomPainter {
  const _BoardDemoPainter({required this.gridColor});

  final Color gridColor;

  @override
  void paint(Canvas canvas, Size size) {
    final cellSize = size.width / 4;

    // 绘制网格
    final gridPaint = Paint()
      ..color = gridColor
      ..strokeWidth = UIConstants.gridLineWidth
      ..style = PaintingStyle.stroke;

    for (var i = 0; i <= 4; i++) {
      // 横线
      canvas.drawLine(
        Offset(0, i * cellSize),
        Offset(size.width, i * cellSize),
        gridPaint,
      );
      // 竖线
      canvas.drawLine(
        Offset(i * cellSize, 0),
        Offset(i * cellSize, size.height),
        gridPaint,
      );
    }

    // 绘制初始棋子
    final positions = [
      // 黑方
      (0, 0, Colors.black),
      (1, 0, Colors.black),
      (2, 0, Colors.black),
      (3, 0, Colors.black),
      // 白方
      (0, 3, Colors.white),
      (1, 3, Colors.white),
      (2, 3, Colors.white),
      (3, 3, Colors.white),
    ];

    for (final (x, y, color) in positions) {
      final center = Offset(
        x * cellSize + cellSize / 2,
        y * cellSize + cellSize / 2,
      );
      final radius = cellSize * 0.3;

      final piecePaint = Paint()
        ..color = color
        ..style = PaintingStyle.fill;

      canvas.drawCircle(center, radius, piecePaint);

      final borderPaint = Paint()
        ..color = color == Colors.black ? Colors.white : Colors.black
        ..strokeWidth = 1.5
        ..style = PaintingStyle.stroke;

      canvas.drawCircle(center, radius, borderPaint);
    }
  }

  @override
  bool shouldRepaint(_BoardDemoPainter oldDelegate) =>
      oldDelegate.gridColor != gridColor;
}
